#ifndef TOUCH_REGION_H
#define TOUCH_REGION_H

#include "ui_types.h"

/* -----------------------------------------------------------------------
 * touch_region.h
 * TEAM CODE (owner: Tony - display and user interface) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: Tony; Brendon (integrator) updated its notes for the fault and debug screens (28 Oct 2026).
 * BJT2 Sound Modulating Toy — Hit Testing and Touch-to-Event Mapping
 * Author: Tony (Display/UI subsystem)
 *
 * Module 3: touch_hit_test — geometric test for a single region.
 * Module 4: touch_get_event — maps a pixel coordinate to a ui_event_t
 *           based on the currently active screen's layout.
 * (Module numbers: the module table in PD5b_Tony/README.md.)
 * ----------------------------------------------------------------------- */

/**
 * touch_hit_test
 * Returns true if pixel (px, py) falls within the given region.
 * Boundary is half-open: the region covers x .. x+w-1 and y .. y+h-1,
 * so a point on x+w or y+h (just past the right / bottom edge) misses.
 * A region with w=0 or h=0 never produces a hit.
 *
 * @param px      X pixel coordinate to test.
 * @param py      Y pixel coordinate to test.
 * @param region  Pointer to the touch_region_t to test against.
 * @return        true if (px, py) is inside region, false otherwise.
 */
bool touch_hit_test(uint16_t px, uint16_t py,
                    const touch_region_t *region);

/**
 * touch_get_event
 * Given a calibrated pixel coordinate and the current screen, returns
 * the ui_event_t associated with whatever region was tapped.
 * Returns EVENT_NONE if the coordinate does not fall inside any
 * defined region for the current screen. On UI_SCREEN_FAULT every
 * coordinate (the HOME corner included) returns EVENT_FAULT_DISMISS;
 * on UI_SCREEN_DEBUG every coordinate returns EVENT_NONE.
 *
 * @param px      Calibrated X pixel coordinate.
 * @param py      Calibrated Y pixel coordinate.
 * @param screen  Currently active screen.
 * @return        The associated ui_event_t, or EVENT_NONE.
 */
ui_event_t touch_get_event(uint16_t px, uint16_t py, ui_screen_t screen);

#endif /* TOUCH_REGION_H */
